// src/hooks/UseExceptions.js
import { useCallback, useEffect, useState } from 'react';
import { get, post, del } from '../api/HttpClient';

const STORAGE_KEY = 'watchservice.exceptions';

function saveLocal(list) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {}
}

function loadLocal() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function useExceptions() {
  const [exceptions, setExceptions] = useState(loadLocal());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const server = await get('/settings/exceptions');
      const list = Array.isArray(server) ? server : [];
      setExceptions(list);
      saveLocal(list);
    } catch (e) {
      setError(e);
      const local = loadLocal();
      setExceptions(local);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const addException = useCallback(async ({ type, pattern, memo }) => {
    const t = String(type || 'PATH').trim();
    const p = String(pattern || '').trim();
    const m = String(memo || '').trim();
    if (!p) return;

    try {
      const created = await post('/settings/exceptions', { type: t, pattern: p, memo: m });
      const next = [created, ...exceptions].filter(Boolean);
      setExceptions(next);
      saveLocal(next);
    } catch (e) {
      // 서버 실패 시 로컬만 추가
      const localId = Date.now();
      const next = [{ id: localId, type: t, pattern: p, memo: m }, ...exceptions];
      setExceptions(next);
      saveLocal(next);
      setError(e);
    }
  }, [exceptions]);

  const removeException = useCallback(async (id) => {
    const prev = exceptions;
    const next = prev.filter((x) => x.id !== id);
    setExceptions(next);
    saveLocal(next);

    try {
      await del(`/settings/exceptions/${id}`);
    } catch (e) {
      setExceptions(prev);
      saveLocal(prev);
      setError(e);
    }
  }, [exceptions]);

  return {
    exceptions,
    loading,
    error,
    refresh,
    addException,
    removeException,
    setExceptions,
  };
}
